sys_ui_action.script:
var metricType='';
var groupAsmt;
var grAsmt = new GlideRecord('asmt_assessment_instance');
grAsmt.addQuery('sn_grc_profile', current.sys_id);
grAsmt.orderBy('metric_type');
grAsmt.orderByDesc('sn_grc_item.name');
grAsmt.query();
var sys_ids = [];
if(grAsmt.hasNext()) {
	grAsmt.next();
	metricType = grAsmt.metric_type.name;
	sys_ids.push(grAsmt.sys_id.toString());
	gs.addInfoMessage('Ctrl: ' + grAsmt.sn_grc_item.name);
}
while (grAsmt.next()) {
gs.addInfoMessage('Ctrl: ' + grAsmt.sn_grc_item.name);
	if(metricType!=grAsmt.metric_type.name) {
		// gs.addInfoMessage('Metric Types are different: ' + grAsmt.metric_type.name + ' - ' + metricType);
		// gs.addInfoMessage('count: ' + sys_ids.length);
		if (sys_ids.length > 1) {
			groupAsmt = new sn_grc.GRCAssessmentUtils().createGroup(sys_ids.toString(), 'grouped', 'sn_grc_profile');
			if(!groupAsmt.success) gs.addErrorMessage('Unable to create group');
			else gs.addInfoMessage(grAsmt.msgs.info);
			// gs.addInfoMessage(groupAsmt.msgs.error + ' - ' + groupAsmt.msgs.info);
			metricType = grAsmt.metric_type.name;

		}
		sys_ids = [];

		// gs.addInfoMessage(grAsmt.metric_type.name +  '  /  ' + metricType);

	}
	sys_ids.push(grAsmt.sys_id.toString());
	// gs.addInfoMessage(sys_ids.toString());
}
		if (sys_ids.length > 1) {
			groupAsmt = new sn_grc.GRCAssessmentUtils().createGroup(sys_ids.toString(), 'grouped', 'sn_grc_profile');
			if(!groupAsmt.success) gs.addErrorMessage('Unable to create group');
			else gs.addInfoMessage(grAsmt.msgs.info);
		}
